INSERT INTO public.blog_posts (title, slug, excerpt, content, status, published_at, meta_title, meta_description, lang, translation_group)
VALUES
(
  'Conserver ses photos de famille : risques réels et solutions durables',
  'conserver-photos-de-famille-risques-et-solutions',
  'Téléphone perdu, disque dur mort, cloud saturé : voici les vrais risques qui menacent vos photos de famille, et une méthode simple pour les mettre à l''abri durablement.',
  $$<p>Nous n'avons jamais pris autant de photos, et jamais autant perdu de photos. Un téléphone tombé dans l'eau, un ordinateur remplacé sans transfert, un compte de messagerie fermé, un disque dur externe rangé dans un tiroir qui ne redémarre plus : chaque famille a son histoire de souvenirs disparus. Le paradoxe est cruel, car la photo numérique donne un sentiment de sécurité trompeur.</p>
<h2>Les cinq risques les plus fréquents</h2>
<p><strong>1. Le point unique de défaillance.</strong> Toutes les photos sur un seul appareil, sans copie : la panne, le vol ou la casse suffisent à tout effacer.</p>
<p><strong>2. L'obsolescence des supports.</strong> Un CD gravé, une carte SD ou un disque dur mécanique vieillissent. Les supports magnétiques et optiques se dégradent silencieusement en quelques années.</p>
<p><strong>3. La dépendance à un service.</strong> Une messagerie, un réseau social ou une application gratuite peut fermer, changer de conditions ou supprimer des comptes inactifs. Vos souvenirs deviennent alors otages d'une décision commerciale.</p>
<p><strong>4. Le désordre.</strong> 40 000 photos non triées équivalent, en pratique, à zéro souvenir consultable. Sans date, sans contexte, sans nom, une image devient anonyme en une génération.</p>
<p><strong>5. La perte du récit.</strong> C'est le risque le plus grave : la photo survit, mais plus personne ne sait qui est sur l'image, où, quand, ni pourquoi elle comptait.</p>
<h2>La règle 3-2-1, adaptée à la famille</h2>
<p>Les professionnels appliquent la règle 3-2-1 : trois copies des données, sur deux types de supports différents, dont une copie hors de votre domicile. Pour une famille, cela donne : les photos sur le téléphone ou l'ordinateur, une sauvegarde sur disque externe, et un espace en ligne sécurisé pour les souvenirs qui comptent vraiment.</p>
<p>Le troisième point est le plus souvent négligé, alors que c'est lui qui protège contre l'incendie, le dégât des eaux ou le cambriolage.</p>
<h2>Trier avant de sauvegarder</h2>
<p>Inutile de tout conserver. Une sélection de 300 photos racontées vaut mieux que 30 000 fichiers muets. Procédez par périodes : une année, un événement, une personne. Pour chaque image retenue, notez trois informations minimales : qui, quand, où. Cette discipline transforme un stock en héritage.</p>
<h2>Pourquoi Family Garden est une solution adaptée</h2>
<p>Family Garden n'est pas un simple espace de stockage : c'est un <a href="/">journal de famille privé</a> où chaque photo est accompagnée de son récit, de sa date, de ses personnes et de son lieu. Concrètement :</p>
<ul>
<li><strong>Un espace privé par défaut</strong> : rien n'est public, rien n'est indexé, rien n'est revendu.</li>
<li><strong>Le contexte avec l'image</strong> : texte, audio, vidéo et photos réunis dans un même souvenir, consultable en <a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">arbre généalogique</a> ou en chronologie.</li>
<li><strong>20 Go de stockage</strong> pour 2,99 €/mois, sans publicité — voir le détail sur la <a href="/tarifs">page tarifs</a>.</li>
<li><strong>Un partage choisi</strong> : vous décidez qui voit quoi, membre par membre.</li>
</ul>
<h2>Par où commencer aujourd'hui</h2>
<p>Choisissez dix photos qui comptent, écrivez trois lignes sur chacune, et enregistrez-les. C'est le geste le plus rentable que vous ferez pour votre mémoire familiale. Vous pouvez tester la démarche en quelques minutes avec la <a href="/demo">démonstration gratuite</a>, sans créer de compte, ou consulter notre guide pour <a href="/blog/conserver-transmettre-souvenirs-de-famille">conserver et transmettre vos souvenirs</a>.</p>$$,
  'published', now(), 'Conserver ses photos de famille : risques et solutions | Family Garden',
  'Disque dur, cloud, téléphone : les vrais risques pour vos photos de famille et la méthode pour les protéger durablement. Guide complet Family Garden.',
  'fr', 'photos-conservation'
),
(
  'Cousinade : organiser, recueillir et conserver les souvenirs de toute la famille',
  'cousinade-organiser-recueillir-conserver-souvenirs',
  'Une cousinade est l''occasion unique de rassembler photos, récits et voix des différentes branches. Voici comment ne rien perdre de cette journée.',
  $$<p>Une cousinade réunit parfois cent personnes qui ne se croisent qu'une fois par décennie. C'est le moment où les albums sortent des placards, où les anciens racontent, où l'on découvre qu'une branche possède les photos que l'autre cherchait depuis vingt ans. Et c'est aussi, trop souvent, une journée qui s'évapore faute d'avoir été recueillie.</p>
<h2>Avant : préparer la collecte</h2>
<p>Un mois avant, demandez à chaque famille d'apporter trois choses : une photo ancienne, un objet qui a une histoire, et le nom d'un ancêtre dont elle sait quelque chose. Prévoyez un coin « atelier mémoire » avec une table, une bonne lumière et un téléphone sur trépied.</p>
<p>Préparez également une liste de questions simples : « Quel est ton plus ancien souvenir de la maison de famille ? », « Qui t'a appris à... ? ». Nos <a href="/blog/raconter-sa-vie-a-ses-enfants-methode">questions guidées pour raconter sa vie</a> fonctionnent parfaitement en cousinade.</p>
<h2>Pendant : trois gestes qui changent tout</h2>
<p><strong>Photographier les photos.</strong> Posez les tirages anciens à plat, sans flash, près d'une fenêtre. En une heure, on numérise cinquante images qui n'existaient qu'en un seul exemplaire.</p>
<p><strong>Enregistrer les voix.</strong> Deux minutes d'enregistrement audio d'une grand-tante valent plus que dix pages écrites après coup. Le grain de la voix, l'accent, le rire : rien de tout cela ne se reconstitue.</p>
<p><strong>Nommer les visages.</strong> Sur chaque photo de groupe, notez immédiatement les prénoms. C'est l'information qui disparaît en premier.</p>
<h2>Après : rassembler au même endroit</h2>
<p>Le piège classique est la dispersion : des photos dans un groupe de messagerie qui expire, d'autres sur une clé USB, les vidéos chez un cousin. Créez plutôt un espace commun où chaque branche dépose ses contributions, avec les dates et les noms.</p>
<p>Family Garden a été conçu pour cet usage : un <a href="/">journal de famille privé</a> où vous créez des cercles de partage par branche, où chaque souvenir est daté et rattaché aux personnes concernées, et où l'<a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">arbre généalogique</a> relie enfin les visages aux noms. Le tout pour 2,99 €/mois — le détail est sur la <a href="/tarifs">page tarifs</a>.</p>
<h2>Le calendrier idéal</h2>
<ul>
<li><strong>J-30</strong> : appel aux contributions, liste des questions, désignation de deux « gardiens de la mémoire ».</li>
<li><strong>Jour J</strong> : atelier numérisation, enregistrements audio, photo de groupe par branche.</li>
<li><strong>J+15</strong> : dépôt en ligne, invitation des familles, relecture collective des légendes.</li>
</ul>
<p>Une cousinade bien recueillie devient la base d'un patrimoine familial consultable par les générations suivantes. Essayez la démarche en quelques minutes avec la <a href="/demo">démo gratuite</a>.</p>$$,
  'published', now(), 'Cousinade : recueillir et conserver les souvenirs de famille | Family Garden',
  'Organiser une cousinade réussie : numériser les photos anciennes, enregistrer les voix, nommer les visages et tout rassembler dans un espace familial privé.',
  'fr', 'cousinade'
),
(
  'Souvenirs de mariage : conserver bien plus que les photos du photographe',
  'souvenirs-de-mariage-conserver-et-transmettre',
  'Discours, messages, préparatifs, anecdotes : le mariage produit une mémoire riche qui disparaît souvent en quelques mois. Voici comment la préserver.',
  $$<p>Le lendemain d'un mariage, il reste un reportage photo, quelques vidéos verticales, un livre d'or et des centaines de messages éparpillés dans des conversations. Six mois plus tard, la clé USB du photographe est rangée quelque part, les vidéos des invités ont disparu avec les téléphones, et personne n'a relu le livre d'or.</p>
<h2>Ce que l'on oublie de conserver</h2>
<ul>
<li>Les <strong>discours</strong> — souvent filmés en morceaux, jamais rassemblés ni transcrits.</li>
<li>Les <strong>préparatifs</strong> : essayages, répétitions, fabrication de la décoration, ces mois de vie commune qui racontent le couple.</li>
<li>Les <strong>photos des invités</strong>, bien plus nombreuses et spontanées que celles du professionnel.</li>
<li>Les <strong>mots écrits</strong> : faire-part, menu, cartes reçues, texte des vœux.</li>
<li>Le <strong>récit</strong> : comment vous vous êtes rencontrés, pourquoi ce lieu, pourquoi cette chanson.</li>
</ul>
<h2>Une méthode simple en trois temps</h2>
<p><strong>Avant.</strong> Ouvrez un souvenir « préparatifs » et ajoutez-y au fil des mois quelques photos et notes. C'est le chapitre que personne ne pense à écrire et que tout le monde adore relire.</p>
<p><strong>Le jour J.</strong> Désignez deux invités « collecteurs ». Leur mission n'est pas de photographier, mais de récupérer : demander à chaque table une photo, enregistrer trente secondes de vœux audio par famille, filmer les discours en entier.</p>
<p><strong>Après.</strong> Dans le mois qui suit, rassemblez tout au même endroit et écrivez le récit de la journée pendant que les détails sont frais : la météo, le trac, la phrase qui a fait rire toute la salle.</p>
<h2>Un espace privé plutôt qu'un album public</h2>
<p>Publier son mariage sur un réseau social, c'est confier des images très personnelles à une plateforme publicitaire, et les voir disparaître dans un fil en 48 heures. Family Garden propose l'inverse : un <a href="/">journal privé</a>, sans publicité, où le mariage devient un chapitre durable, partagé uniquement avec les personnes que vous invitez. Vous pouvez créer un cercle « invités » et laisser chacun consulter, sans que rien ne soit indexé par les moteurs de recherche.</p>
<p>Comparez d'ailleurs les deux approches dans notre article sur <a href="/blog/family-garden-vs-reseaux-sociaux-souvenirs">Family Garden face aux réseaux sociaux</a>.</p>
<h2>Et dix ans plus tard ?</h2>
<p>Un mariage bien archivé devient un point de repère dans la <a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">chronologie familiale</a> : les enfants y découvrent leurs parents jeunes, les petits-enfants y entendent la voix d'arrière-grands-parents disparus. C'est exactement l'usage pour lequel Family Garden a été conçu, à 2,99 €/mois avec 20 Go d'espace (<a href="/tarifs">voir les tarifs</a>).</p>
<p>Envie d'essayer avant de vous inscrire ? La <a href="/demo">démonstration</a> prend deux minutes.</p>$$,
  'published', now(), 'Souvenirs de mariage : les conserver et les transmettre | Family Garden',
  'Discours, préparatifs, photos des invités, vœux : comment rassembler et préserver tous les souvenirs de mariage dans un espace familial privé et durable.',
  'fr', 'mariage'
),
(
  'Journal de naissance : créer le carnet numérique des premières années',
  'journal-de-naissance-carnet-numerique-enfant',
  'Premiers mois, premiers mots, premiers pas : comment tenir un journal d''enfant simple, régulier et durable, à offrir plus tard à votre enfant.',
  $$<p>Les parents photographient énormément la première année, puis beaucoup moins. Et surtout, ils écrivent peu. Or ce sont les mots qui manquent le plus vingt ans après : l'heure exacte de la naissance, le prénom envisagé puis abandonné, la phrase drôle prononcée à trois ans, la peur du premier jour d'école.</p>
<h2>Ce qu'un journal d'enfant devrait contenir</h2>
<ul>
<li><strong>Les faits</strong> : date, heure, poids, lieu, personnes présentes, contexte de l'époque.</li>
<li><strong>Les premières fois</strong> : sourire, nuit complète, dent, pas, mot, vélo, rentrée.</li>
<li><strong>Les mots d'enfant</strong>, notés tels quels, sans les corriger.</li>
<li><strong>La voix</strong> : un court enregistrement chaque année, à la même date. C'est saisissant à relire dix ans plus tard.</li>
<li><strong>Les lettres</strong> : un message écrit par chaque parent, à ouvrir à 18 ans.</li>
</ul>
<h2>Le rythme qui tient dans la durée</h2>
<p>Un journal quotidien ne survit jamais aux nuits difficiles. Visez plutôt une entrée par mois la première année, puis une par trimestre, plus un « bilan d'anniversaire » annuel avec une photo, une taille, une passion du moment et une anecdote. Cinq minutes, quatre fois par an, suffisent à construire un récit complet.</p>
<h2>Une mémoire partagée avec les grands-parents</h2>
<p>Les grands-parents éloignés sont souvent réduits à recevoir des photos dans une messagerie qui s'efface. En les invitant dans un cercle de partage, ils suivent l'enfant grandir et peuvent eux-mêmes ajouter leurs souvenirs : la ressemblance avec un ancêtre, la même robe de baptême portée trois générations plus tôt. Ces liens apparaissent naturellement dans l'<a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">arbre généalogique</a>.</p>
<h2>Pourquoi ne pas simplement utiliser son téléphone</h2>
<p>Parce qu'un téléphone se perd, que la galerie n'accepte pas les récits, et que les réseaux sociaux exposent un enfant qui n'a rien demandé. Family Garden garde tout dans un <a href="/">espace privé</a>, sans publicité et sans indexation, avec 20 Go pour 2,99 €/mois (<a href="/tarifs">détail des tarifs</a>). Vous pouvez même programmer la remise d'un souvenir à une date future, par exemple les 18 ans de votre enfant.</p>
<h2>Commencer ce soir</h2>
<p>Ouvrez un premier souvenir intitulé « Le jour de ta naissance » et écrivez dix lignes. Puis ajoutez une photo. Le reste suivra. Pour voir à quoi cela ressemble, essayez la <a href="/demo">démo gratuite</a> ou lisez notre méthode pour <a href="/blog/raconter-sa-vie-a-ses-enfants-methode">raconter sa vie à ses enfants</a>.</p>$$,
  'published', now(), 'Journal de naissance numérique : carnet des premières années | Family Garden',
  'Créer un journal d''enfant durable : premières fois, mots d''enfant, enregistrements, lettres à ouvrir plus tard. Méthode simple et espace familial privé.',
  'fr', 'naissance'
),
(
  'Ateliers souvenirs en EHPAD et en milieu hospitalier : la mémoire comme soin',
  'ateliers-souvenirs-ehpad-hopital-alzheimer',
  'Réminiscence, thérapie par l''évocation, livre de vie : comment les supports de souvenirs numériques accompagnent les personnes âgées et les patients Alzheimer.',
  $$<p>Dans les EHPAD, les unités Alzheimer et certains services hospitaliers, les ateliers mémoire font partie du quotidien. Ils reposent sur un principe simple : la mémoire ancienne, dite autobiographique, résiste souvent bien plus longtemps que la mémoire immédiate. Une photo de mariage, une chanson des années 1960 ou le nom d'un village suffisent parfois à rouvrir la parole chez une personne qui ne s'exprimait plus.</p>
<p><em>Cet article présente des usages courants en établissement. Il ne constitue pas un avis médical : toute démarche doit être conduite avec l'équipe soignante et le consentement de la personne ou de ses proches.</em></p>
<h2>Ce qu'est la thérapie par réminiscence</h2>
<p>La thérapie par réminiscence consiste à stimuler l'évocation de souvenirs personnels à l'aide de supports : photographies, objets, musiques, odeurs, documents. Elle est largement pratiquée en gériatrie pour favoriser la communication, valoriser l'identité de la personne et apaiser certains moments d'anxiété. Elle s'appuie souvent sur un « livre de vie » (life story book) rassemblant les repères biographiques du résident.</p>
<h2>Les limites du classeur papier</h2>
<p>Le livre de vie papier reste précieux, mais il s'abîme, se perd lors des transferts d'établissement, ne contient ni voix ni vidéo, et ne peut pas être alimenté à distance par la famille. Un support numérique privé résout ces trois limites.</p>
<h2>Comment un espace de souvenirs numérique aide concrètement</h2>
<ul>
<li><strong>Une biographie structurée</strong> : lieux de vie, métier, mariage, enfants, passions, autant de repères disponibles pour l'équipe soignante et les intervenants.</li>
<li><strong>Des supports variés</strong> : photos, enregistrements de la voix des petits-enfants, courtes vidéos, musiques associées à une époque.</li>
<li><strong>Une chronologie visuelle</strong> : parcourir une décennie après l'autre facilite l'ancrage temporel pendant l'atelier.</li>
<li><strong>Une contribution à distance</strong> : la famille enrichit le contenu depuis chez elle, l'animateur y accède en séance.</li>
<li><strong>Une continuité</strong> : le contenu suit la personne d'un établissement à l'autre.</li>
</ul>
<h2>Conduire un atelier en pratique</h2>
<p>Prévoyez des séances courtes, de vingt à trente minutes, avec un thème unique : l'enfance, le métier, les vacances, le mariage. Présentez trois à cinq supports maximum, laissez de longs silences, ne corrigez pas les erreurs de dates et notez ce qui a suscité une réaction pour la séance suivante. Nos <a href="/blog/revivre-ses-souvenirs-denfance">pistes sur les souvenirs d'enfance</a> fournissent de bonnes amorces.</p>
<h2>Confidentialité : un point non négociable</h2>
<p>Les données de vie d'une personne vulnérable sont sensibles. Family Garden est un <a href="/">journal privé</a> : rien n'est public, rien n'est indexé, rien n'est exploité à des fins publicitaires, et l'accès se donne nominativement, membre par membre — l'inverse d'un groupe de messagerie ou d'un réseau social. Les modalités d'accès et le fonctionnement sont détaillés dans notre <a href="/faq">FAQ</a> et sur la <a href="/tarifs">page tarifs</a> (2,99 €/mois, 20 Go).</p>
<p>Familles et établissements peuvent tester la création d'un souvenir en deux minutes via la <a href="/demo">démonstration</a>.</p>$$,
  'published', now(), 'Ateliers souvenirs EHPAD et Alzheimer : la mémoire comme soin | Family Garden',
  'Réminiscence, livre de vie, ateliers mémoire en EHPAD et à l''hôpital : comment un espace de souvenirs numérique privé soutient les personnes âgées et leurs familles.',
  'fr', 'medical-memoire'
),
(
  'Souvenirs de voyage et de vacances : du carnet de route au récit de famille',
  'souvenirs-de-voyage-vacances-carnet-numerique',
  'Comment transformer 2 000 photos de vacances en un récit de voyage que votre famille relira vraiment, année après année.',
  $$<p>Au retour d'un voyage, la plupart des familles rapportent deux mille photos et aucun récit. Quelques images circulent, puis tout retombe dans la pellicule du téléphone. Trois étés plus tard, personne ne sait plus si la photo du marché a été prise en Sicile ou au Portugal.</p>
<h2>Le carnet de route en trois lignes par jour</h2>
<p>La méthode la plus efficace est aussi la plus simple : chaque soir, trois lignes. Où nous étions, ce que nous avons fait, une chose remarquée. Ajoutez une seule photo, celle du jour, pas les quarante autres. En deux semaines, vous obtenez un véritable carnet de voyage, écrit sur le moment, avec les détails que la mémoire efface : le prix du café, la chaleur, le prénom du guide.</p>
<h2>Sélectionner au retour</h2>
<p>Consacrez une heure au retour : gardez trente à cinquante photos, supprimez les doublons et les images floues, puis nommez les lieux. Une photo légendée « Ravello, terrasse de la villa, août 2026 » vaut cent fichiers IMG_4821.</p>
<h2>Ce qui rend un souvenir de voyage vivant</h2>
<ul>
<li><strong>Les sons</strong> : dix secondes de vagues, de marché, de gare, enregistrés sur place.</li>
<li><strong>Les objets</strong> : billet de train, carte postale, ticket de musée, photographiés à plat.</li>
<li><strong>Les personnes</strong> : ceux avec qui vous voyagiez, et non seulement les paysages.</li>
<li><strong>Les ratés</strong> : la panne, la pluie, la route manquée. Ce sont les histoires que l'on raconte encore vingt ans après.</li>
</ul>
<h2>Relier les voyages entre eux</h2>
<p>L'intérêt d'un journal familial apparaît sur la durée : la carte des lieux visités se remplit, la chronologie montre les étés successifs, et l'on retrouve la même plage à trente ans d'écart, avec deux générations différentes. Family Garden réunit photos, textes, sons et lieux dans un même <a href="/">journal de famille privé</a>, consultable par décennie, et relie les personnes via l'<a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">arbre généalogique</a>.</p>
<h2>Partager sans tout exposer</h2>
<p>Publier ses vacances en temps réel sur un réseau social signale aussi que le logement est vide, expose les enfants et laisse la plateforme exploiter les images. Un partage privé, réservé aux proches invités, offre le même plaisir sans les inconvénients — nous détaillons ce point dans <a href="/blog/partager-ses-souvenirs-en-famille-en-securite">partager ses souvenirs en toute sécurité</a>.</p>
<p>Comptez 2,99 €/mois avec 20 Go d'espace (<a href="/tarifs">voir les tarifs</a>), ou testez d'abord la <a href="/demo">démo gratuite</a>.</p>$$,
  'published', now(), 'Souvenirs de voyage : créer un carnet de vacances durable | Family Garden',
  'Transformer ses photos de vacances en récit de voyage : méthode du carnet en trois lignes, tri, sons, objets et partage privé en famille.',
  'fr', 'voyage'
),
(
  'Conserver la mémoire des ancêtres grâce à l''arbre généalogique',
  'conserver-memoire-des-ancetres-arbre-genealogique',
  'Des dates sur un arbre ne racontent rien. Voici comment rattacher photos, récits et voix à chaque ancêtre pour transmettre une histoire, pas un tableau.',
  $$<p>La généalogie classique produit des tableaux impeccables : noms, dates, lieux, actes d'état civil. Mais un arrière-grand-père réduit à « 1897-1962 » ne dit rien à un enfant de dix ans. Ce qui se transmet, ce sont les histoires : le métier, l'exil, la maison, la recette, la phrase qu'il répétait.</p>
<h2>Passer de l'arbre au récit</h2>
<p>Pour chaque ancêtre connu, essayez de réunir cinq éléments :</p>
<ul>
<li>Une <strong>photo</strong>, même de mauvaise qualité, même de groupe.</li>
<li>Un <strong>lieu</strong> : village d'origine, maison, atelier, ferme.</li>
<li>Un <strong>métier</strong> ou une activité, avec ce qu'il impliquait au quotidien.</li>
<li>Une <strong>anecdote</strong> transmise oralement, même incertaine, en le précisant.</li>
<li>Un <strong>document</strong> : lettre, livret militaire, faire-part, carte postale.</li>
</ul>
<h2>Interroger les vivants avant les archives</h2>
<p>Les archives départementales seront encore là dans trente ans ; votre grand-mère de 88 ans, non. Commencez par enregistrer les témoignages : une heure d'entretien avec un aîné apporte souvent plus qu'un mois de recherche en ligne. Posez des questions concrètes : la maison, les repas, l'école, le travail, la guerre, les fêtes. Notre <a href="/blog/raconter-sa-vie-a-ses-enfants-methode">méthode en 7 étapes</a> peut servir de trame d'entretien.</p>
<h2>Un arbre qui porte les souvenirs</h2>
<p>Dans Family Garden, l'arbre généalogique n'est pas un schéma isolé : chaque personne peut porter ses photos, sa biographie, ses lieux de vie et les souvenirs où elle apparaît. On clique sur un ancêtre et l'on accède à son histoire, pas seulement à ses dates. L'import GEDCOM permet de récupérer un arbre déjà constitué ailleurs, puis de l'enrichir en photos et en récits.</p>
<p>L'arbre généalogique est proposé en option à 5 €/mois en complément de l'abonnement à 2,99 €/mois (<a href="/tarifs">détail sur la page tarifs</a>). Le fonctionnement est décrit dans le guide <a href="/blog/arbre-genealogique-en-ligne-photos-et-souvenirs">arbre généalogique en ligne avec photos et souvenirs</a>.</p>
<h2>Transmettre plutôt qu'archiver</h2>
<p>Un patrimoine familial n'existe que s'il est consulté. Invitez vos cousins à compléter les branches qu'ils connaissent mieux, organisez une <a href="/blog/cousinade-organiser-recueillir-conserver-souvenirs">cousinade</a> pour numériser les albums, et veillez à ce que plusieurs personnes disposent d'un accès. C'est ainsi qu'une mémoire traverse les générations.</p>$$,
  'published', now(), 'Mémoire des ancêtres : enrichir son arbre généalogique | Family Garden',
  'Photos, récits, lieux et témoignages : comment rattacher une véritable histoire à chaque ancêtre de votre arbre généalogique et la transmettre durablement.',
  'fr', 'ancetres'
),
(
  'Revivre ses souvenirs d''enfance : pourquoi et comment les écrire',
  'revivre-ses-souvenirs-denfance',
  'Odeurs, cours de récréation, dimanches chez les grands-parents : une méthode douce pour retrouver ses souvenirs d''enfance et les mettre par écrit.',
  $$<p>Les souvenirs d'enfance ne disparaissent pas : ils deviennent inaccessibles faute de déclencheur. Une odeur de cire, une chanson, une photo de classe suffisent parfois à faire remonter une scène entière que l'on croyait perdue. Écrire ces souvenirs, c'est se les réapproprier, et c'est aussi offrir à ses enfants un accès rare à l'enfant que l'on a été.</p>
<h2>Pourquoi cela fait du bien</h2>
<p>Se remémorer volontairement des épisodes positifs de sa vie est une pratique utilisée en accompagnement psychologique et en gériatrie : elle renforce le sentiment de continuité et d'identité. Sans en faire une thérapie, écrire son enfance apaise, remet de l'ordre dans une histoire personnelle et permet souvent de comprendre autrement ses propres parents.</p>
<h2>Vingt déclencheurs efficaces</h2>
<ul>
<li>La disposition exacte de votre chambre d'enfant.</li>
<li>Le trajet vers l'école, à pied ou en voiture.</li>
<li>Le repas du dimanche : qui cuisinait, qui parlait le plus fort.</li>
<li>Le jeu de la cour de récréation, avec ses règles précises.</li>
<li>La télévision ou la radio du soir.</li>
<li>Les vacances : le départ, la voiture chargée, l'arrivée.</li>
<li>Une maladie, une peur, une bêtise et sa punition.</li>
<li>Un objet fétiche, un vêtement détesté, un cadeau marquant.</li>
<li>Le prénom de votre meilleur ami de CE2.</li>
<li>Une odeur : cuisine, grenier, cave, atelier, savon.</li>
</ul>
<p>Prenez un déclencheur, écrivez dix minutes sans vous relire. La forme importe peu ; la précision sensorielle, beaucoup.</p>
<h2>Utiliser la voix plutôt que le clavier</h2>
<p>Beaucoup de personnes racontent bien mais écrivent difficilement. L'enregistrement audio résout le problème : parlez trois minutes, comme si vous répondiez à un petit-enfant. La voix ajoute une émotion qu'aucun texte ne restitue, et elle deviendra elle-même un souvenir précieux.</p>
<h2>Où les conserver</h2>
<p>Un carnet se perd, un fichier texte s'égare. Family Garden regroupe ces récits dans un <a href="/">journal de famille privé</a>, classés par décennie et rattachés aux personnes concernées dans l'<a href="/blog/conserver-memoire-des-ancetres-arbre-genealogique">arbre familial</a>. Des questions guidées vous proposent chaque semaine une nouvelle amorce, ce qui évite la page blanche.</p>
<p>Vous pouvez écrire votre premier souvenir d'enfance dès maintenant via la <a href="/demo">démonstration gratuite</a>, ou suivre notre <a href="/blog/raconter-sa-vie-a-ses-enfants-methode">méthode en 7 étapes</a> pour aller plus loin. L'abonnement complet est à 2,99 €/mois (<a href="/tarifs">tarifs</a>).</p>$$,
  'published', now(), 'Souvenirs d''enfance : comment les retrouver et les écrire | Family Garden',
  'Déclencheurs sensoriels, questions guidées, enregistrement de la voix : une méthode simple pour revivre ses souvenirs d''enfance et les transmettre.',
  'fr', 'enfance'
),
(
  'Partager ses souvenirs avec la famille et les amis en toute sécurité',
  'partager-ses-souvenirs-en-famille-en-securite',
  'Groupes de messagerie, albums partagés, réseaux sociaux : où finissent réellement vos photos, et comment organiser un partage familial vraiment maîtrisé.',
  $$<p>Partager des photos de famille est devenu si simple que l'on ne se demande plus où elles atterrissent. Un groupe de messagerie, un album public par lien, une publication « entre amis » : dans les trois cas, vous perdez la maîtrise de la diffusion, et parfois la propriété de l'usage qui est fait des images.</p>
<h2>Les trois risques du partage ordinaire</h2>
<p><strong>Le lien qui circule.</strong> Un album accessible « à toute personne disposant du lien » est, en pratique, public : il suffit d'un transfert pour qu'il échappe à votre cercle.</p>
<p><strong>La perte de contexte.</strong> Dans une conversation de groupe, les photos se noient. Trois mois plus tard, elles sont introuvables, et la conversation finit par être supprimée.</p>
<p><strong>L'exposition des mineurs.</strong> Publier régulièrement des photos d'enfants construit, sans leur consentement, une identité numérique qu'ils n'ont pas choisie.</p>
<h2>Ce qu'est un partage réellement maîtrisé</h2>
<ul>
<li><strong>Nominatif</strong> : chaque personne est invitée individuellement, pas par un lien anonyme.</li>
<li><strong>Segmenté</strong> : la branche paternelle ne voit pas forcément les mêmes souvenirs que les amis proches.</li>
<li><strong>Révocable</strong> : un accès doit pouvoir être retiré à tout moment.</li>
<li><strong>Non indexé</strong> : aucun moteur de recherche ne doit pouvoir atteindre le contenu.</li>
<li><strong>Sans exploitation publicitaire</strong> : vos images ne servent ni au ciblage, ni à l'entraînement de modèles.</li>
</ul>
<h2>Comment fonctionne le partage dans Family Garden</h2>
<p>Family Garden repose sur des cercles de partage : vous créez un cercle (famille proche, cousins, amis), vous y invitez des personnes nommément, puis vous choisissez quels souvenirs sont visibles par quel cercle. Tout est privé par défaut ; rien n'est publié, rien n'est indexé. Un accès peut être retiré, et chaque souvenir garde son contexte, sa date et ses personnes.</p>
<p>Pour les questions de conservation à long terme et de transmission, consultez notre <a href="/faq">FAQ</a>, ou l'article sur la <a href="/blog/conserver-photos-de-famille-risques-et-solutions">conservation des photos de famille</a>.</p>
<h2>Trois bonnes pratiques immédiates</h2>
<ol>
<li>Demandez l'accord des personnes majeures avant de diffuser une photo où elles figurent.</li>
<li>Réservez les photos d'enfants aux cercles privés, jamais aux publications ouvertes.</li>
<li>Faites l'inventaire de vos anciens albums partagés par lien et désactivez-les.</li>
</ol>
<p>L'abonnement Family Garden est à 2,99 €/mois avec 20 Go d'espace (<a href="/tarifs">voir les tarifs</a>). Vous pouvez essayer sans compte grâce à la <a href="/demo">démonstration</a>.</p>$$,
  'published', now(), 'Partager ses souvenirs de famille en toute sécurité | Family Garden',
  'Groupes de messagerie, albums par lien, réseaux sociaux : les risques du partage ordinaire et comment organiser un partage familial privé, nominatif et révocable.',
  'fr', 'partage-securise'
),
(
  'Family Garden ou les réseaux sociaux : où conserver ses souvenirs de famille ?',
  'family-garden-vs-reseaux-sociaux-souvenirs',
  'Un réseau social est conçu pour capter l''attention, pas pour conserver une mémoire familiale. Comparatif honnête sur la vie privée, la durabilité et le partage.',
  $$<p>Beaucoup de familles utilisent un réseau social comme album : c'est gratuit, tout le monde y est, et le partage est immédiat. Sur le papier, l'outil semble suffisant. Dans les faits, il répond à un objectif très différent du vôtre.</p>
<h2>Un modèle économique qui n'est pas le vôtre</h2>
<p>Un réseau social gratuit se rémunère par la publicité et l'analyse des comportements. Son but est de maximiser le temps passé, pas de préserver une mémoire familiale sur cinquante ans. Vos souvenirs y sont un contenu parmi d'autres, servant à alimenter un fil.</p>
<h2>Comparaison point par point</h2>
<ul>
<li><strong>Vie privée</strong> — Réseau social : paramètres complexes, portée réelle difficile à vérifier, données exploitées. Family Garden : privé par défaut, aucune indexation, aucune publicité.</li>
<li><strong>Durabilité</strong> — Réseau social : compte supprimable, conditions modifiables, format non exportable simplement. Family Garden : contenu structuré, exportable, pensé pour la transmission.</li>
<li><strong>Organisation</strong> — Réseau social : un fil chronologique inversé où tout se noie. Family Garden : chronologie par décennie, catégories, personnes, lieux, arbre généalogique.</li>
<li><strong>Partage</strong> — Réseau social : « amis », listes approximatives, captures d'écran faciles. Family Garden : cercles nominatifs, accès révocable, souvenir par souvenir.</li>
<li><strong>Récit</strong> — Réseau social : légendes courtes, format image. Family Garden : texte long, audio, vidéo, documents, dates et contexte.</li>
<li><strong>Coût</strong> — Réseau social : gratuit, financé par vos données. Family Garden : 2,99 €/mois, financé par votre abonnement (<a href="/tarifs">voir les tarifs</a>).</li>
</ul>
<h2>Le test des vingt ans</h2>
<p>Posez-vous une question simple : dans vingt ans, vos petits-enfants pourront-ils retrouver la photo de votre mariage, savoir qui figure dessus et entendre la voix de leur arrière-grand-mère ? Sur un réseau social, la réponse dépend d'une entreprise, d'un mot de passe oublié et d'une politique de comptes inactifs. Dans un journal familial privé conçu pour cela, elle dépend de vous.</p>
<h2>Les deux peuvent coexister</h2>
<p>Rien n'interdit de publier une photo de vacances sur un réseau social. La règle utile est de séparer les usages : la conversation publique d'un côté, la mémoire familiale de l'autre, dans un <a href="/">espace privé</a> où chaque souvenir est daté, raconté et relié aux personnes concernées.</p>
<p>Pour aller plus loin, lisez <a href="/blog/partager-ses-souvenirs-en-famille-en-securite">partager ses souvenirs en toute sécurité</a> et <a href="/blog/conserver-photos-de-famille-risques-et-solutions">conserver ses photos de famille</a>, ou testez la <a href="/demo">démo gratuite</a> en deux minutes.</p>$$,
  'published', now(), 'Family Garden vs réseaux sociaux : où garder ses souvenirs ? | Family Garden',
  'Vie privée, durabilité, organisation, partage : comparatif entre les réseaux sociaux et un journal de famille privé pour conserver vos souvenirs sur le long terme.',
